def sh(cmd, cwd=None, check=True):
    print("$ %s" % (cmd if isinstance(cmd, str) else " ".join(cmd)), flush=True)
    r = subprocess.run(cmd, cwd=cwd, shell=isinstance(cmd, str), capture_output=True, text=True)
    if r.stdout:
        print(r.stdout[-4000:], flush=True)
    if r.stderr:
        print(r.stderr[-4000:], file=sys.stderr, flush=True)
    if check and r.returncode != 0:
        raise SystemExit("command failed rc=%d" % r.returncode)
    return r


def device_report():
    import torch
    print("torch %s  cuda=%s" % (torch.__version__, torch.cuda.is_available()), flush=True)
    if torch.cuda.is_available():
        cc = torch.cuda.get_device_capability(0)
        print("device %s  CC %d.%d" % (torch.cuda.get_device_name(0), cc[0], cc[1]), flush=True)
        if cc[0] < 7:
            print("WARN: CC < 7.0 (P100?). fp32 arm, so slow-but-correct.", flush=True)
    else:
        print("WARN: no CUDA. This will be slow but correct.", flush=True)


def audit_checkpoint(path):
    """Refuse to load a checkpoint that names a callable which could execute logic.

    weights_only=True cannot be used here: the file embeds a pathlib.PosixPath, which is off the
    allowlist. So the pickle is DISASSEMBLED without executing it and every referenced global is
    checked. This is the kernel-side copy of scripts/promoteratlas_pickle_audit.py -- the safety
    decision travels with the run instead of being asserted in a memo.
    """
    found = {}
    with zipfile.ZipFile(path) as z:
        for pk in [n for n in z.namelist() if n.endswith(".pkl")]:
            strings = []
            for op, arg, _pos in pickletools.genops(io.BytesIO(z.read(pk))):
                if op.name in ("SHORT_BINUNICODE", "BINUNICODE", "UNICODE"):
                    strings.append(arg)
                elif op.name == "STACK_GLOBAL" and len(strings) >= 2:
                    found["%s.%s" % (strings[-2], strings[-1])] = 1
                elif op.name in ("GLOBAL", "INST"):
                    found[str(arg).replace(" ", ".")] = 1
    bad = [g for g in found
           if not any(g == p or g.startswith(p) for p in SAFE_GLOBAL_PREFIXES)]
    print("checkpoint globals: %s" % sorted(found), flush=True)
    if bad:
        raise SystemExit("REFUSED: checkpoint names non-container globals: %s" % bad)
    print("checkpoint audit: OK (no callable that could execute logic)", flush=True)


def load_atlas():
    import importlib.util, pathlib, torch
    src = PA / "src/promoter_atlas/models/dna_transformer.py"
    spec = importlib.util.spec_from_file_location("pa_dt", src)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    w = PA / "trained_weights/base_model/promoteratlas-base.pt"
    audit_checkpoint(w)
    # The checkpoint embeds a pathlib.PosixPath (an unused training-config path). On Linux -- i.e.
    # on Kaggle -- it instantiates fine. On Windows it raises NotImplementedError, which blocks the
    # local dry run, so alias it there and ONLY there, so this cannot perturb the real run.
    # Found by scripts/promoteratlas_arm_dryrun.py: the first version saved the original and never
    # wrote the assignment that does the work.
    if os.name == "nt":
        pathlib.PosixPath = pathlib.WindowsPath
    ck = torch.load(w, map_location="cpu", weights_only=False)
    model = mod.DNATransformer(dim=128, n_blocks=8, n_heads=8)
    res = model.load_state_dict(ck["model_state_dict"], strict=True)
    n = sum(p.numel() for p in model.parameters())
    print("atlas loaded: %d params, missing=%s unexpected=%s"
          % (n, list(res.missing_keys), list(res.unexpected_keys)), flush=True)
    if n != EXPECTED_PARAMS:
        raise SystemExit("REFUSED: %d params, bar expects %d" % (n, EXPECTED_PARAMS))
    print("pretraining config: %s" % {k: str(v) for k, v in (ck.get("config") or {}).items()
                                      if k in ("n_point_masks", "n_window_masks", "window_size")},
          flush=True)
    model.eval()
    return model


NUC = {"A": 0, "C": 1, "G": 2, "T": 3}


def embed(model, seqs, width, device, batch=256):
    """Masked mean-pool of the final latent over the UNPADDED positions -> (N,128).

    width == len(seq) is the NATIVE geometry (primary). width > len(seq) zero-pads, which is how
    pretraining encoded a MASKED base -- measured to perturb the pooled embedding (max |delta| 1.232)
    even under masked pooling, because attention lets those columns reach the real positions. Run as
    the declared secondary cell so the geometry change is auditable.
    """
    import numpy as np, torch
    out = np.zeros((len(seqs), 128), dtype=np.float32)
    with torch.no_grad():
        for i in range(0, len(seqs), batch):
            chunk = seqs[i:i + batch]
            X = torch.zeros((len(chunk), 4, width))
            for b, s in enumerate(chunk):
                for j, c in enumerate(s):
                    k = NUC.get(c)
                    if k is not None:
                        X[b, k, j] = 1.0
            X = X.to(device)
            _, _, z = model(X, return_latent=True)
            L = len(chunk[0])
            out[i:i + len(chunk)] = z[:, :, :L].mean(dim=2).float().cpu().numpy()
            if i % (batch * 40) == 0:
                print("   embedded %d/%d (%.0fs)" % (i, len(seqs), time.time() - T0), flush=True)
    return out


def ridge_spearman(Xtr, ytr_raw, Xte, yte_raw, spearman, shuffle_seed=None):
    """Mirrors dna_decode.glm.expression.fit_predict_ridge EXACTLY: StandardScaler, Ridge(alpha=1.0),
    fit on log1p(expression), score Spearman against RAW expression. Any deviation makes the number
    incomparable with the committed incumbent tables, which is the whole point of the reconcile gate.
    """
    import numpy as np
    from sklearn.linear_model import Ridge
    from sklearn.preprocessing import StandardScaler
    ytr = np.log1p(np.asarray(ytr_raw, dtype=float))
    if shuffle_seed is not None:
        rng = np.random.default_rng(90_000 + shuffle_seed)
        ytr = ytr.copy()
        rng.shuffle(ytr)
    sc = StandardScaler().fit(Xtr)
    m = Ridge(alpha=ALPHA).fit(sc.transform(Xtr), ytr)
    pred = m.predict(sc.transform(Xte))
    return float(spearman(list(pred), list(yte_raw))), [float(v) for v in pred]


def main(smoke=False):
    import numpy as np, torch
    # A Kaggle script kernel runs with NO arguments, so --smoke is unreachable there. The flag stays
    # for the local dry run; on Kaggle the __main__ block below calls main(smoke=True) and then
    # main(smoke=False), which is the smoke-then-full order fragment_pyramid_kernel established.
    smoke = smoke or ("--smoke" in sys.argv)
    limit = 6000 if smoke else 0
    n_seeds = 2 if smoke else N_SEEDS

    device_report()
    WORK.mkdir(parents=True, exist_ok=True)
    (WORK / "genomewide.py").write_bytes(gzip.decompress(base64.b64decode(GENOMEWIDE_B64)))
    sys.path.insert(0, str(WORK))
    import genomewide as gw
    print("genomewide embedded: PEAK_TILE_FILE=%s" % gw.PEAK_TILE_FILE, flush=True)

    if not PA.exists():
        sh(["git", "clone", "--depth", "1", PA_URL, str(PA)])
    sh(["git", "rev-parse", "HEAD"], cwd=str(PA), check=False)

    model = load_atlas()
    dev = "cuda" if torch.cuda.is_available() else "cpu"
    model = model.to(dev)

    # on-device determinism -- restated here because local CPU said 0.0 and the device may differ
    probe = ["ACGT" * 37 + "AA"] * 4
    d1 = embed(model, probe, 150, dev)
    d2 = embed(model, probe, 150, dev)
    det = float(np.abs(d1 - d2).max())
    print("determinism on %s: max|delta| = %.3e" % (dev, det), flush=True)

    tiles_all = gw.load_peak_tiles(CACHE, allow_download=True)
    tiles = [t for t in tiles_all if t.category == "tile" and len(t.seq) == 150]
    print("tiles: %d loaded, %d after filter(category=='tile', len==150)"
          % (len(tiles_all), len(tiles)), flush=True)
    if not smoke and len(tiles) != EXPECTED_TILES:
        raise SystemExit("REFUSED: %d tiles, bar expects %d" % (len(tiles), EXPECTED_TILES))
    if limit:
        tiles = tiles[:limit]

    seqs = [t.seq for t in tiles]
    feats = {}
    for geo in GEOMETRIES:
        print("embedding geometry %s (width %d) ..." % (geo["name"], geo["width"]), flush=True)
        feats[geo["name"]] = embed(model, seqs, geo["width"], dev)

    prim = feats[GEOMETRIES[0]["name"]]
    var = prim.var(axis=0)
    nconst = int((var < 1e-8).sum())
    sub = prim[:512]
    nrm = sub / (np.linalg.norm(sub, axis=1, keepdims=True) + 1e-12)
    cos = nrm @ nrm.T
    np.fill_diagonal(cos, np.nan)
    mean_cos = float(np.nanmean(cos))
    print("embedding sanity: %d constant dims, mean inter-tile cosine %.4f" % (nconst, mean_cos),
          flush=True)

    gc_all = np.asarray(gw.gc_features(seqs), dtype=float)

    arms = {g["name"]: {} for g in GEOMETRIES}
    gc_by_seed, null_by_seed, split_ok, pertile = {}, {}, {}, {}
    for seed in range(n_seeds):
        train, test, nheld = gw.leave_peak_out(tiles, frac=FRAC, seed=seed)
        tid = {id(t) for t in test}
        idx_te = [i for i, t in enumerate(tiles) if id(t) in tid]
        idx_tr = [i for i, t in enumerate(tiles) if id(t) not in tid]
        assert len(idx_te) == len(test) and all(tiles[i] is t for i, t in zip(idx_te, test))
        sha = hashlib.sha256(",".join(str(i) for i in idx_te).encode()).hexdigest()[:32]
        exp = SPLITS.get(str(seed), {})
        ok = (not smoke) and sha == exp.get("sha")
        split_ok[str(seed)] = {"sha": sha, "expected": exp.get("sha"), "match": bool(ok),
                               "n_test": len(idx_te), "expected_n_test": exp.get("n_test"),
                               "held_out_peaks": nheld}
        print("seed %d: n_test %d (expect %s) peaks %d  split_sha %s  match=%s"
              % (seed, len(idx_te), exp.get("n_test"), nheld, sha, ok), flush=True)

        ytr = [tiles[i].expression for i in idx_tr]
        yte = [tiles[i].expression for i in idx_te]

        for g in GEOMETRIES:
            X = feats[g["name"]]
            sp, pred = ridge_spearman(X[idx_tr], ytr, X[idx_te], yte, gw.spearman)
            arms[g["name"]][str(seed)] = round(sp, 4)
            if g is GEOMETRIES[0]:
                pertile[str(seed)] = {"tile_indices": idx_te, "pred": [round(v, 6) for v in pred]}
            print("   %-22s spearman %.4f" % (g["name"], sp), flush=True)

        gsp, _ = ridge_spearman(gc_all[idx_tr], ytr, gc_all[idx_te], yte, gw.spearman)
        gc_by_seed[str(seed)] = round(gsp, 4)
        nsp, _ = ridge_spearman(prim[idx_tr], ytr, prim[idx_te], yte, gw.spearman,
                                shuffle_seed=seed)
        null_by_seed[str(seed)] = round(nsp, 4)
        print("   gc anchor %.4f   shuffled-label null %.4f" % (gsp, nsp), flush=True)

    def med(d):
        v = sorted(d.values())
        n = len(v)
        return round((v[n // 2] if n % 2 else 0.5 * (v[n // 2 - 1] + v[n // 2])), 4)

    art = {
        "schema": "promoteratlas-tile-arm-v1",
        "arm": ARM, "date": time.strftime("%Y-%m-%d"), "smoke": smoke,
        "bar": "wiki/promoteratlas_arm_acceptance_bar.json",
        "device": dev, "determinism_max_abs_delta": det,
        "n_tiles_scored": len(tiles), "n_seeds": n_seeds,
        "geometry_primary": GEOMETRIES[0]["name"],
        "embedding_sanity": {"n_constant_dims": nconst, "mean_inter_tile_cosine": round(mean_cos, 4)},
        "split_reconcile": split_ok,
        "arms": {k: {"per_seed": v, "median": med(v)} for k, v in arms.items()},
        "gc_anchor": {"per_seed": gc_by_seed, "median": med(gc_by_seed),
                      "seed0": gc_by_seed.get("0"),
                      "expected_seed0": GC_ANCHOR_SEED0, "tol": GC_ANCHOR_TOL},
        "shuffled_label_null": {"per_seed": null_by_seed, "median": med(null_by_seed)},
        "incumbent_per_seed": INCUMBENT,
        "per_tile_predictions": pertile,
        "wall_seconds": round(time.time() - T0, 1),
    }

    # ---- verdict, in the bar's frozen check order: 7 5 6 4 1 2 3 ----
    v, detail = None, ""
    if not smoke and not all(x["match"] for x in split_ok.values()):
        v = "INVALID_SPLIT_MISMATCH"
        detail = "held-out tile_indices differ from the committed tables; no comparison is valid"
    elif smoke:
        v, detail = "SMOKE_NOT_SCOREABLE", "subsampled pool cannot reproduce the full split"
    else:
        gc0 = gc_by_seed.get("0")
        if gc0 is None or abs(gc0 - GC_ANCHOR_SEED0) > GC_ANCHOR_TOL:
            v = "INVALID_PIPELINE_ANCHOR_MISSED"
            detail = ("gc seed0 %.4f vs expected %.4f +/- %.4f -- the pipeline cannot reproduce a "
                      "known number, so it cannot establish a new one"
                      % (gc0 if gc0 is not None else float("nan"), GC_ANCHOR_SEED0, GC_ANCHOR_TOL))
        elif abs(med(null_by_seed) - med(gc_by_seed)) < MARGIN and abs(med(null_by_seed)) >= MARGIN:
            v = "INVALID_NULL_SCORED"
            detail = "shuffled-label null median %.4f is outside the %.2f bar" % (med(null_by_seed), MARGIN)
        elif nconst > 0 or mean_cos >= 0.95:
            v = "INVALID_DEGENERATE_EMBEDDING"
            detail = "%d constant dims, mean inter-tile cosine %.4f" % (nconst, mean_cos)
        else:
            am = med(arms[GEOMETRIES[0]["name"]])
            conv = [INCUMBENT[str(s)]["conv"] for s in range(n_seeds)]
            convmed = round(sorted(conv)[len(conv) // 2], 4)
            wins = sum(1 for s in range(n_seeds)
                       if arms[GEOMETRIES[0]["name"]][str(s)] > INCUMBENT[str(s)]["conv"])
            maxtx = [INCUMBENT[str(s)]["max_tx"] for s in range(n_seeds)]
            maxtxmed = round(sorted(maxtx)[len(maxtx) // 2], 4)
            art["paired_vs_conv"] = {"atlas_median": am, "conv_median": convmed,
                                     "delta_median": round(am - convmed, 4), "seeds_won": wins,
                                     "n_seeds": n_seeds}
            if am >= maxtxmed + MARGIN:
                v, detail = "ATLAS_BEATS_THERMODYNAMIC", "%.4f >= %.4f + %.2f" % (am, maxtxmed, MARGIN)
            elif am >= convmed + MARGIN and wins >= 8:
                v, detail = "ATLAS_ADDS_ALONE", "%.4f vs conv %.4f, %d/%d seeds" % (am, convmed, wins, n_seeds)
            elif abs(am - convmed) <= MARGIN:
                v, detail = "ATLAS_TIES_CONV", "%.4f vs conv %.4f within %.2f" % (am, convmed, MARGIN)
            else:
                v, detail = "ATLAS_LOSES_ALONE", "%.4f vs conv %.4f" % (am, convmed)

    art["verdict"], art["verdict_detail"] = v, detail
    name = "promoteratlas_tile_arm_%s.json" % ("smoke" if smoke else "full")
    (WORK / name).write_text(json.dumps(art, indent=1), encoding="utf-8")
    print("\nVERDICT: %s\n  %s\nwrote %s  (%.1fs)" % (v, detail, name, time.time() - T0), flush=True)
    return 0


if __name__ == "__main__":
    try:
        if "--smoke" in sys.argv or "--full-only" in sys.argv:
            # local dry run, or an explicit single-phase request
            raise SystemExit(main(smoke="--smoke" in sys.argv))
        # SMOKE THEN FULL. Spending the full run on a code path that has never executed against
        # the REAL substrate is the thing being avoided -- the local dry run stubs load_peak_tiles,
        # so the GEO download and the real tile structure are untested until the smoke runs here.
        print("=" * 78 + "\nPHASE 1/2: SMOKE\n" + "=" * 78, flush=True)
        rc = main(smoke=True)
        if rc != 0:
            print("smoke phase returned %r -- NOT starting the full run" % rc, flush=True)
            raise SystemExit(rc)
        if not (WORK / "promoteratlas_tile_arm_smoke.json").exists():
            print("smoke wrote no artifact -- NOT starting the full run", flush=True)
            raise SystemExit(1)
        print("\n" + "=" * 78 + "\nPHASE 2/2: FULL\n" + "=" * 78, flush=True)
        raise SystemExit(main(smoke=False))
    except SystemExit:
        raise
    except Exception:
        import traceback
        traceback.print_exc()
        # A DISTINCT filename, never a verdict file. Kaggle returns no output files for an ERROR
        # kernel, so "no log" distinguishes nothing; this exits 0-with-a-failure-artifact instead.
        (WORK / "promoteratlas_tile_arm_failure.json").write_text(
            json.dumps({"schema": "promoteratlas-tile-arm-failure-v1",
                        "traceback": traceback.format_exc(),
                        "note": "a failure artifact is NEVER a verdict"}, indent=1),
            encoding="utf-8")
        raise SystemExit(1)
